    for key in (*gaps.SIDES, 'Head'): g.set(inp.outputs[key], gap.inputs[key])
    axis, origin, lateral = (gap.outputs[k] for k in ('Axis', 'Origin', 'Lateral'))
    cell, minimum = (inp.outputs[k] for k in ('Cell Size', 'Minimum Width'))
    p = _Partition(g, inp.outputs['Pavement'], axis, origin, cell, minimum)
    p.checks.append(gap.outputs['Valid'])
    wires = {key: bridge._wire(g, inp.outputs[key], axis, i, origin, shared=True)
             for i, key in enumerate(gaps.SIDES)}
    curves = {key: value[0] for key, value in wires.items()}
    p.checks.extend(value[4] for value in wires.values())
    query = lambda name, s: wires[name][5](s)
    table = gap.outputs['Stations']; metric = g.named('st_bu_metric', 'FLOAT')
    # Contacts use the gap reader's strict roots. Inserted contact knots can
    # have roundoff residuals, so do not root the zero threshold a second time.
    contacts = gaps._select(g, gap.outputs['Events'], g.compare(g.named('st_bu_event'), 1, kind='INT'))
    contacts = p.sort(contacts, metric)
    bases = _roots(g, table, minimum)
    start_gap = g.sample(table, g.named('st_bu_gap', 'FLOAT'), 0, 'FLOAT')
    end_gap = g.sample(table, g.named('st_bu_gap', 'FLOAT'), g.math('SUBTRACT', bridge._size(g, table), 1.), 'FLOAT')
    p.checks.extend((g.compare(bridge._size(g, contacts), 2, kind='INT'),
        g.compare(bridge._size(g, gap.outputs['Events']), 2, kind='INT'),
        g.compare(bridge._size(g, bases), 2, kind='INT'),
        g.compare(start_gap, minimum, 'GREATER_THAN'), g.compare(end_gap, minimum, 'GREATER_THAN')))
    mouths = {}
    for key, rank in (('Head', 0), ('Tail', None)):
        source = curves['Side A']; last = g.math('SUBTRACT', bridge._size(g, source), 1.)
        first = g.sample(source, p.identity, last if rank is None else rank)
        ordered, _, _, _, good, _ = surface._chain(g, inp.outputs[key], first, 0)
        p.checks.append(good)
        indices = []
        for side in ('A', 'B'):
            curve = curves['Inner '+side]
            at = 0 if rank == 0 else g.math('SUBTRACT', bridge._size(g, curve), 1.)
            identity = g.sample(curve, p.identity, at)
            same = g.compare(p.identity, identity, kind='INT')
            p.checks.append(g.compare(g.stat(ordered, same, output='Sum'), 1.))
            indices.append(g.stat(ordered, g.math('MULTIPLY', same, p.index), output='Sum'))
        a, b = indices
        p.checks.append(g.compare(a, b, 'LESS_THAN'))
        mouths[key] = dict(A=p.select(ordered, 0, a), grass=p.select(ordered, a, b),
            B=p.select(ordered, b, g.math('SUBTRACT', bridge._size(g, ordered), 1.)))
    caps = []; grass = []; tips = []; amplitudes = []
    for at, sign in enumerate((1., -1.)):
        base = g.sample(bases, metric, at, 'FLOAT'); contact = g.sample(contacts, metric, at, 'FLOAT')
        amp = g.math('MINIMUM', g.math('MULTIPLY', .4, minimum),
            g.math('MULTIPLY', .4, g.math('ABSOLUTE', g.math('SUBTRACT', contact, base))))
        amplitudes.append(amp)
        theta = g.math('MULTIPLY', p.index, math.pi/8.)
        station = g.math('ADD', base, g.math('MULTIPLY', sign, g.math('MULTIPLY', amp, g.math('SINE', theta))))
        # Make endpoints exact; sin(pi) is not zero in single precision.
        station = g.switch(g.either(g.compare(p.index, 0), g.compare(p.index, 8)), station, base)
        u = g.math('MULTIPLY', .5, g.math('SUBTRACT', 1., g.math('COSINE', theta)))
