    count = g.math('ADD', count, g.compare(g.math('FLOORED_MODULO', count, 2.), target, 'NOT_EQUAL'))
    p.checks.extend((g.compare(count, LIMIT, 'LESS_EQUAL'), g.compare(tips[1], tips[0], 'GREATER_THAN')))
    count = g.math('MINIMUM', count, LIMIT)
    s = g.math('ADD', tips[0], g.math('MULTIPLY', g.math('SUBTRACT', tips[1], tips[0]),
        g.math('DIVIDE', p.index, g.math('SUBTRACT', count, 1.))))
    oa, ia, ib, ob = [query(key, s) for key in gaps.SIDES]
    a, b, span = [g.vector('DOT_PRODUCT', g.vector('SUBTRACT', v, oa), lateral) for v in (ia, ib, ob)]
    r = g.math('SUBTRACT', span, b); aa = g.math('MULTIPLY', a, a); rr = g.math('MULTIPLY', r, r)
    peak = g.switch(g.compare(b, a, 'GREATER_EQUAL'), g.math('DIVIDE', g.math('ADD',
        g.math('MULTIPLY', a, rr), g.math('MULTIPLY', b, aa)), g.math('ADD', aa, rr)),
        g.math('MULTIPLY', .5, g.math('ADD', a, b)))
